import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const madKingPhysicalScenarios=['mad-king-attack','mad-king-resist','mad-king-counter','mad-king-cancel','mad-king-teleport','mad-king-recover'] as const;
export type MadKingPhysicalScenario=typeof madKingPhysicalScenarios[number];
export function isMadKingPhysicalScenario(name:string):name is MadKingPhysicalScenario{return (madKingPhysicalScenarios as readonly string[]).includes(name);}
export function madKingPhysicalMode(name:MadKingPhysicalScenario){return{recover:name==='mad-king-recover',counter:name==='mad-king-counter',resist:name==='mad-king-resist',cancel:name==='mad-king-cancel',teleport:name==='mad-king-teleport',card:'a2-p17-r3c1',name:'狂王陣'};}
export function makeMadKingPhysicalScenario(name:MadKingPhysicalScenario,players:{id:string;name:string}[],options:{level?:number;none?:boolean;guardian?:boolean;spirit?:number}={}){
 const m=madKingPhysicalMode(name);let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,['白魔術師シェリム','魔導王ガイナス','魔聖母ディア','侍大将のシン'][i]!);for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit=20+6-gameStats(s,p.id).spirit;}s.players[a]!.permanent!.magic_level=20+(options.level??5)-gameStats(s,a).magic_level;
 s.players[b]!.permanent!.spirit=(s.players[b]!.permanent!.spirit??0)+(options.spirit??(m.resist||m.teleport||m.recover?14:2))-gameStats(s,b).spirit;
 const front=options.none?null:takeCard(s,b,options.guardian?'守護者':'メタルゴーレム'),rear=options.none||options.guardian?null:takeCard(s,b,'兵士'),metal=options.none?null:takeCard(s,c,'水竜'),keep=[takeCard(s,a,m.card),takeCard(s,a,'a2-p24-r1c2'),takeCard(s,m.counter?b:a,'必勝の祈り'),takeCard(s,d,'命運凶変'),...[front,rear,metal].filter((x):x is string=>!!x),...(m.counter?['a2-p15-r3c2','a2-p06-r1c1']:['a2-p06-r1c1','a2-p05-r3c1','a2-p07-r1c1']).map(id=>takeCard(s,b,id))];for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(1)},r=transition(s,input,e);if(!r.ok)throw Error(`MAD_KING_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('MAD_KING_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('MAD_KING_IDS');}
 for(const p of players){for(const cardInstanceId of (p.id===b?[front,rear]:p.id===c?[metal]:[]).filter((x):x is string=>!!x))act(p.id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});act(p.id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});return s;
}
